const LEVELS = [["=="], ["<"], ["+", "-"], ["*", "/"]]; // lowest precedence first

// Each method parses one grammar rule and returns its subtree as an S-expression.
class Parser {
  constructor(line) {
    this.toks = (line.match(/\d+|\w+|==|=>|\S/g) || []).concat([""]); // "" is the end of the line
    this.pos = 0;
  }
  peek() {
    return this.toks[this.pos];
  }
  accept(want) {
    if (this.peek() !== want) return false;
    this.pos++;
    return true;
  }
  fail() {
    const tok = this.peek();
    throw new Error("syntax error: unexpected " + (tok ? "'" + tok + "'" : "end of line"));
  }
  expect(want) {
    if (!this.accept(want)) this.fail();
    return want;
  }
  name() { // any word that is not a keyword
    const tok = this.peek();
    if (!/^[A-Za-z_]/.test(tok) || KEYWORDS.has(tok)) this.fail();
    this.pos++;
    return tok;
  }
  items(item) { // item ("," item)* ")" or just ")"
    if (this.accept(")")) return [];
    const result = [item()];
    while (this.accept(",")) result.push(item());
    this.expect(")");
    return result;
  }
  expr() {
    if (this.accept("fn")) {
      this.expect("(");
      const params = this.items(() => this.name()).join(" ");
      this.expect("=>");
      return "(fn (" + params + ") " + this.expr() + ")";
    }
    if (this.accept("if")) {
      const cond = this.expr();
      this.expect("then");
      const yes = this.expr();
      this.expect("else");
      return "(if " + cond + " " + yes + " " + this.expr() + ")";
    }
    return this.binary(0);
  }
  binary(level) { // one loop per level: left-associative
    if (level === LEVELS.length) return this.call();
    let left = this.binary(level + 1);
    while (LEVELS[level].includes(this.peek())) {
      const op = this.expect(this.peek());
      left = "(" + op + " " + left + " " + this.binary(level + 1) + ")";
    }
    return left;
  }
  call() { // f(1)(2): a call's result can be called again
    let node = this.primary();
    while (this.accept("(")) node = ["(call", node, ...this.items(() => this.expr())].join(" ") + ")";
    return node;
  }
  primary() {
    if (this.accept("(")) {
      const node = this.expr();
      this.expect(")");
      return node;
    }
    if (/^\d+$/.test(this.peek()) || this.peek() === "true" || this.peek() === "false") return this.expect(this.peek());
    return this.name();
  }
}

